type I18nContextValue = { language: Language; setLanguage: (language: Language) => void; toggleLanguage: () => void; t: (key: string, variables?: Record<string, string | number>) => string };
const I18nContext = createContext<I18nContextValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('hometown-language') as Language | null) ?? 'en');
  useEffect(() => { localStorage.setItem('hometown-language', language); document.documentElement.lang = language; }, [language]);
  const value = useMemo<I18nContextValue>(() => {
    const dictionary = language === 'vi' ? vi : en;
    const t = (key: string, variables: Record<string, string | number> = {}) => Object.entries(variables).reduce((text, [name, replacement]) => text.replaceAll(`{${name}}`, String(replacement)), dictionary[key] ?? en[key] ?? key);
    return { language, setLanguage, toggleLanguage: () => setLanguage((current) => current === 'en' ? 'vi' : 'en'), t };
  }, [language]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() { const context = useContext(I18nContext); if (!context) throw new Error('useI18n must be used inside LanguageProvider'); return context; }

export function localizedColorName(name: string, t: I18nContextValue['t']) { return t(`color.${name}`); }
export function localizedStockStatus(status: string, t: I18nContextValue['t']) { return status === 'in-stock' ? t('common.stockIn') : status === 'unavailable' ? t('common.stockUnavailable') : t('common.stockMade'); }
export function localizedStatus(status: string, t: I18nContextValue['t']) { const key: Record<string, string> = { PENDING: 'common.statusPending', CONFIRMED: 'common.statusConfirmed', IN_PRODUCTION: 'common.statusProduction', SHIPPED: 'common.statusShipped', COMPLETED: 'common.statusCompleted', CANCELLED: 'common.statusCancelled' }; return t(key[status] ?? status); }
